        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def get_pos(key, default=(0, 0)):
        p = observation.get(key, default)
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            return p[0], p[1]
        return default

    def best_by_manhattan(items, sx, sy, prefer_far=False):
        best = None
        best_score = None
        for item in items or []:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            x, y = item[0], item[1]
            score = abs(x - sx) + abs(y - sy)
            if prefer_far:
                score = -score
            if best is None or score < best_score:
                best = (x, y)
                best_score = score
        return best

    def step_toward(sx, sy, tx, ty):
        return clamp_move(sign(tx - sx), sign(ty - sy))

    def step_away(sx, sy, tx, ty):
        return clamp_move(-sign(tx - sx), -sign(ty - sy))

