        opp = observation.get("opponent_base") or observation.get("opponent_position")
        if isinstance(opp, (list, tuple)) and len(opp) >= 2:
            return step_toward(sx, sy, opp[0], opp[1])
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_by_manhattan(resources, sx, sy, prefer_far=False)
    if target is not None:
        return step_toward(sx, sy, target[0], target[1])

    if ox != sx or oy != sy:
        return step_toward(sx, sy, ox, oy)

